//!src/config/cron-default-destinations.ts
function listCronDefaultDestinationChannels(e){const t=[];const add=(e,n,r=false)=>{const i=n?.channel?.trim();if(i&&i.toLowerCase()!==`last`&&n?.mode!==`webhook`)t.push({path:`${e}.channel`,channel:i,globalFailureAlert:r})};add(`cron.delivery`,e?.delivery);add(`cron.failureAlert`,e?.failureAlert,true);const n={agents:e?.agents,creators:e?.creators};for(const[e,t]of Object.entries(n))for(const[n,r]of Object.entries(t??{})){add(`cron.${e}.${n}.delivery`,r?.delivery);add(`cron.${e}.${n}.failureAlert`,r?.failureAlert)}return t}export{listCronDefaultDestinationChannels as t};